import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class ImmutableListBuilderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String describe(ImmutableListBuilder b) {
        if (b == null) {
            return "<null builder>";
        }
        try {
            return String.valueOf(b.build());
        } catch (RuntimeException e) {
            return "<threw " + e.getClass().getSimpleName() + ">";
        }
    }

    static int sizeOf(ImmutableListBuilder b) {
        return b == null ? -1 : b.size();
    }

    public static void main(String[] args) {
        ImmutableListBuilder empty = new ImmutableListBuilder();
        ImmutableListBuilder one = empty.add("a");
        ImmutableListBuilder two = one == null ? null : one.add("b");

        check("empty.size() after two adds", 0, sizeOf(empty));
        check("empty.build()", "[]", describe(empty));
        check("one.build()", "[a]", describe(one));
        check("two.build()", "[a, b]", describe(two));
        check("one.size() is still 1", 1, sizeOf(one));
        check("add returns a new object", false, one == empty);

        List<String> more = new ArrayList<>(Arrays.asList("c", "d"));
        ImmutableListBuilder three = two == null ? null : two.addAll(more);
        check("two.addAll([c, d])", "[a, b, c, d]", describe(three));
        check("two is unchanged by addAll", "[a, b]", describe(two));

        more.add("e");
        check("later change to the caller's list does not leak in", "[a, b, c, d]", describe(three));

        List<String> snapshot = three == null ? new ArrayList<>() : three.build();
        String outcome;
        try {
            snapshot.add("zzz");
            outcome = "no exception";
        } catch (UnsupportedOperationException e) {
            outcome = "UnsupportedOperationException";
        }
        check("build() result rejects add", "UnsupportedOperationException", outcome);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

