import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * TASK: Build a PERSISTENT builder -- every "change" returns a new builder and
 * the one you called it on stays exactly as it was.
 *
 *   ImmutableListBuilder empty = new ImmutableListBuilder();
 *   ImmutableListBuilder one   = empty.add("a");
 *   empty.size() -> 0     one.size() -> 1
 *
 * add(item)      returns a NEW builder holding this builder's items plus item.
 * addAll(items)  returns a NEW builder with all of them appended, and takes a
 *                defensive copy so later changes to the caller's list cannot
 *                leak in.
 * build()        returns an UNMODIFIABLE snapshot list -- calling add on it
 *                throws UnsupportedOperationException.
 * size()         how many items this builder holds.
 *
 * The private constructor that takes a list is there so add/addAll can hand
 * their new contents to a fresh builder. Nothing may ever mutate the items
 * field of an existing builder.
 */
public class ImmutableListBuilder {

    private final List<String> items;

    public ImmutableListBuilder() {
        this.items = new ArrayList<>();
    }

    private ImmutableListBuilder(List<String> items) {
        this.items = items;
    }

    public ImmutableListBuilder add(String item) {
        List<String> next = new ArrayList<>(this.items);
        next.add(item);
        return new ImmutableListBuilder(next);
    }

    public ImmutableListBuilder addAll(List<String> more) {
        List<String> next = new ArrayList<>(this.items);
        next.addAll(more);
        return new ImmutableListBuilder(next);
    }

    public List<String> build() {
        return Collections.unmodifiableList(new ArrayList<>(this.items));
    }

    public int size() {
        return this.items.size();
    }
}
